10	/// Storage interface behind the memories MCP tools.
11	///
12	/// Implementations should return paths relative to the memory store and enforce
13	/// their own storage-specific access rules. The local implementation uses the
14	/// filesystem today; a later implementation can satisfy the same contract from a
15	/// remote backend.
16	pub trait MemoriesBackend: Clone + Send + Sync + 'static {
17	    fn list(
18	        &self,
19	        request: ListMemoriesRequest,
20	    ) -> impl Future<Output = Result<ListMemoriesResponse, MemoriesBackendError>> + Send;
21	
22	    fn read(
23	        &self,
24	        request: ReadMemoryRequest,
25	    ) -> impl Future<Output = Result<ReadMemoryResponse, MemoriesBackendError>> + Send;
26	
27	    fn search(
28	        &self,
29	        request: SearchMemoriesRequest,
30	    ) -> impl Future<Output = Result<SearchMemoriesResponse, MemoriesBackendError>> + Send;
31	}
