101	#[derive(Debug, thiserror::Error)]
102	pub enum MemoriesBackendError {
103	    #[error("path '{path}' {reason}")]
104	    InvalidPath { path: String, reason: String },
105	    #[error("cursor '{cursor}' {reason}")]
106	    InvalidCursor { cursor: String, reason: String },
107	    #[error("line_offset must be a 1-indexed line number")]
108	    InvalidLineOffset,
109	    #[error("max_lines must be a positive integer")]
110	    InvalidMaxLines,
111	    #[error("line_offset exceeds file length")]
112	    LineOffsetExceedsFileLength,
113	    #[error("path '{path}' is not a file")]
114	    NotFile { path: String },
115	    #[error("query must not be empty")]
116	    EmptyQuery,
117	    #[error("I/O error while reading memories: {0}")]
118	    Io(#[from] std::io::Error),
119	}
