121	impl MemoriesBackendError {
122	    pub fn invalid_path(path: impl Into<String>, reason: impl Into<String>) -> Self {
123	        Self::InvalidPath {
124	            path: path.into(),
125	            reason: reason.into(),
126	        }
127	    }
128	
129	    pub fn invalid_cursor(cursor: impl Into<String>, reason: impl Into<String>) -> Self {
130	        Self::InvalidCursor {
131	            cursor: cursor.into(),
132	            reason: reason.into(),
133	        }
134	    }
135	}
