273	async fn search_file(
274	    root: &Path,
275	    path: &Path,
276	    query: &str,
277	    matches: &mut Vec<MemorySearchMatch>,
278	) -> Result<(), MemoriesBackendError> {
279	    let content = match tokio::fs::read_to_string(path).await {
280	        Ok(content) => content,
281	        Err(err) if err.kind() == std::io::ErrorKind::InvalidData => return Ok(()),
282	        Err(err) => return Err(err.into()),
283	    };
284	    for (idx, line) in content.lines().enumerate() {
285	        if line.contains(query) {
286	            matches.push(MemorySearchMatch {
287	                path: display_relative_path(root, path),
288	                line_number: idx + 1,
289	                line: line.to_string(),
290	            });
291	        }
292	    }
293	    Ok(())
294	}
