178	pub async fn run_stdio_server(codex_home: &AbsolutePathBuf) -> anyhow::Result<()> {
179	    let backend = LocalMemoriesBackend::from_codex_home(codex_home);
180	    tokio::fs::create_dir_all(backend.root())
181	        .await
182	        .with_context(|| format!("create memories root at {}", backend.root().display()))?;
183	    MemoriesMcpServer::new(backend)
184	        .serve((tokio::io::stdin(), tokio::io::stdout()))
185	        .await?
186	        .waiting()
187	        .await?;
188	    Ok(())
189	}
