    root: &Path,
    path: &Path,
    query: &str,
    context_lines: usize,
    case_sensitive: bool,
    matches: &mut Vec<MemorySearchMatch>,
) -> Result<(), MemoriesBackendError> {
    let content = match tokio::fs::read_to_string(path).await {
        Ok(content) => content,
        Err(err) if err.kind() == std::io::ErrorKind::InvalidData => return Ok(()),
        Err(err) => return Err(err.into()),
    };
    let lines: Vec<&str> = content.lines().collect();
    let lowered_query = case_sensitive.then(String::new).map_or_else(
        || query.to_lowercase(),
        |_| String::new(),
    );
    for (idx, line) in lines.iter().enumerate() {
        let is_match = if case_sensitive {
            line.contains(query)
        } else {
            line.to_lowercase().contains(&lowered_query)
        };
        if is_match {
            let start = idx.saturating_sub(context_lines);
            let end = (idx + context_lines).min(lines.len() - 1);
            let window = lines[start..=end].join("\n");
            matches.push(MemorySearchMatch {
                path: display_relative_path(root, path),
                line_number: idx + 1,
                start_line_number: start + 1,
                content: window,
            });
        }
